from __future__ import annotations

import json
from pathlib import Path

_CACHE: dict[str, int] = {}
_SCHEMA_PATH = Path(__file__).parent / "schema.yaml"


def _load_schema() -> dict[str, int]:
    if _CACHE:
        return _CACHE
    # schema.yaml is generated by tools/dump_offsets.py
    try:
        import yaml
        with _SCHEMA_PATH.open("r", encoding="utf-8") as fh:
            data = yaml.safe_load(fh) or {}
        _CACHE.update(data.get("offsets", {}))
    except FileNotFoundError:
        pass
    return _CACHE


def resolve(name: str) -> int:
    """Return the byte offset for a named field in client.dll."""
    schema = _load_schema()
    if name not in schema:
        raise KeyError(f"offset '{name}' missing from schema.yaml — "
                       f"run tools/dump_offsets.py against the current build")
    return schema[name]


def reload_schema(path: Path | str) -> None:
    global _SCHEMA_PATH
    _SCHEMA_PATH = Path(path)
    _CACHE.clear()
    _load_schema()